// A libFuzzer entry point that is compiled together with the RasterWebPCore sources.

/// Parses one input generated by libFuzzer.
@_cdecl("LLVMFuzzerTestOneInput")
public func fuzzContainer(_ data: UnsafePointer<UInt8>?, _ count: Int) -> CInt {
    let bytes = unsafe UnsafeBufferPointer(start: data, count: count)
    _ = try? unsafe WebPImageInfo(parsing: bytes.span)
    return 0
}
